"""An age we could not read must never earn the maximum freshness multiplier.

freshness() is the news decay multiplier every scored card pays. For an age it cannot parse there
are exactly two honest answers: refuse the input, or treat the item as old. Answering 1.0 gives the
strongest possible multiplier to the item we know least about, which is how an undated scrape
outranks a dated one. The real ages are pinned too, so a repair cannot buy the property by
flattening the curve.
"""
import pytest

import lib


def _verdict(value):
    """The freshness this input earns, or None when the primitive refuses it (also correct)."""
    try:
        return lib.freshness(value)
    except (TypeError, ValueError):
        return None


@pytest.mark.parametrize("undated", [None, "", "unknown", "n/a", {}])
def test_an_unreadable_age_never_earns_the_top_multiplier(undated):
    got = _verdict(undated)
    if got is None:
        return
    assert got < 1.0, (
        "an age of %r scored %r, the same multiplier a brand new item earns" % (undated, got))


def test_a_real_age_is_still_scored_the_way_it_always_was():
    assert lib.freshness(0) == 1.0
    assert lib.freshness(1.0) > lib.freshness(24.0) > lib.freshness(240.0)
    assert 0.0 < lib.freshness(240.0) <= 1.0
